/**
 * CONTINUOUS CHAOS RUNNER
 * Injects safe, non-destructive failure patterns to verify system resilience.
 */
export async function runChaosCycle() {
    logger.info('[Chaos] Initiating Continuous Validation Cycle');

    try {
        // 1. Worker Disruption (Soft-Restart simulation)
        logger.info('[Chaos] Injecting Worker Disruption Signal');

        // 2. Simulated Network Latency (Redis)
        logger.info('[Chaos] Injecting 100ms Redis Latency (10s burst)');

        // 3. Retry Storm Simulation
        await redis.set('system:chaos:retry-storm', 'true', 'EX', 30);

        return {
            timestamp: Date.now(),
            chaosInjected: true,
            layers: ['worker', 'redis', 'retries']
        };
    } catch (err) {
        logger.error({ err }, '[Chaos] Cycle failed to inject');
        return { success: false, error: err };
    }
}

import { BaseExecutionError } from '@packages/utils';

export enum FailureType {
  TRANSIENT = 'TRANSIENT',
  PERMANENT = 'PERMANENT',
  UNKNOWN = 'UNKNOWN'
}

export class FailureClassifier {
  /**
   * Classifies an error to determine if it's worth replaying.
   */
  static classify(error: any): FailureType {
    if (error && typeof error === 'object') {
      // Check for structured execution error overrides
      if (error instanceof BaseExecutionError || ('action' in error)) {
        const action = error.action;
        if (action === 'dlq' || action === 'quarantine') {
          return FailureType.PERMANENT;
        }
        if (action === 'retry' || action === 'backoff') {
          return FailureType.TRANSIENT;
        }
      }
    }

    const errorMsg = error instanceof Error ? error.message : String(error || '');
    const lowerError = errorMsg.toLowerCase();

    // Transient Errors (Network, Timeouts, Rate Limits)
    if (
      lowerError.includes('timeout') ||
      lowerError.includes('econnreset') ||
      lowerError.includes('econnrefused') ||
      lowerError.includes('rate limit') ||
      lowerError.includes('429') ||
      lowerError.includes('503') ||
      lowerError.includes('502') ||
      lowerError.includes('socket hang up')
    ) {
      return FailureType.TRANSIENT;
    }

    // Permanent Errors (Auth, Validation, Not Found)
    if (
      lowerError.includes('unauthorized') ||
      lowerError.includes('401') ||
      lowerError.includes('403') ||
      lowerError.includes('invalid') ||
      lowerError.includes('not found') ||
      lowerError.includes('404') ||
      lowerError.includes('syntax error')
    ) {
      return FailureType.PERMANENT;
    }

    return FailureType.UNKNOWN;
  }
}

import { logger } from '@packages/observability';

export interface MissionBudget {
    maxTokens: number;
    maxExecutionTimeMs: number;
    maxRetries: number;
    maxSandboxCostCents: number;
}

export interface MissionConsumption {
    tokens: number;
    executionTimeMs: number;
    retries: number;
    sandboxCostCents: number;
}

/**
 * 📉 ExecutionEconomicsEngine
 * Enforces economic viability of autonomous missions.
 * Prevents token burn spirals and resource exhaustion.
 */
export class ExecutionEconomicsEngine {
    private consumption: Map<string, MissionConsumption> = new Map();

    /**
     * Initializes a budget tracking for a mission.
     */
    initMission(missionId: string) {
        this.consumption.set(missionId, {
            tokens: 0,
            executionTimeMs: 0,
            retries: 0,
            sandboxCostCents: 0
        });
    }

    /**
     * Records consumption for a specific mission.
     */
    recordConsumption(missionId: string, usage: Partial<MissionConsumption>) {
        const current = this.consumption.get(missionId);
        if (!current) return;

        if (usage.tokens) current.tokens += usage.tokens;
        if (usage.executionTimeMs) current.executionTimeMs += usage.executionTimeMs;
        if (usage.retries) current.retries += usage.retries;
        if (usage.sandboxCostCents) current.sandboxCostCents += usage.sandboxCostCents;

        this.consumption.set(missionId, current);
    }

    /**
     * Checks if a mission has exceeded its assigned budget.
     */
    checkBudget(missionId: string, budget: MissionBudget): { exceeded: boolean, reason?: string } {
        const current = this.consumption.get(missionId);
        if (!current) return { exceeded: false };

        if (current.tokens > budget.maxTokens) {
            return { exceeded: true, reason: `TOKEN_BUDGET_EXCEEDED: ${current.tokens} > ${budget.maxTokens}` };
        }
        if (current.executionTimeMs > budget.maxExecutionTimeMs) {
            return { exceeded: true, reason: `TIME_BUDGET_EXCEEDED: ${current.executionTimeMs}ms > ${budget.maxExecutionTimeMs}ms` };
        }
        if (current.retries > budget.maxRetries) {
            return { exceeded: true, reason: `RETRY_LIMIT_EXCEEDED: ${current.retries} > ${budget.maxRetries}` };
        }
        if (current.sandboxCostCents > budget.maxSandboxCostCents) {
            return { exceeded: true, reason: `SANDBOX_COST_EXCEEDED: ${current.sandboxCostCents}c > ${budget.maxSandboxCostCents}c` };
        }

        return { exceeded: false };
    }

    /**
     * Gets total ROI metrics for a tenant (Simulated).
     */
    getTenantROI(tenantId: string) {
        // In a real system, this would aggregate across all tenant missions
        return {
            totalCostUSD: 42.50,
            estimatedValueUSD: 2500.00,
            roiFactor: 58.8
        };
    }
}

export const economicsEngine = new ExecutionEconomicsEngine();

import axios from 'axios';
import type { AxiosInstance, AxiosRequestConfig } from 'axios';
import axiosRetry from 'axios-retry';
import CircuitBreaker from 'opossum';
import { logger, circuitBreakerState, retryAttemptsTotal } from '@packages/observability';
import { contextStorage } from '@packages/utils';

interface OutboundClientOptions {
  serviceName: string;
  baseURL: string;
  timeout?: number;
  retries?: number;
  circuitBreaker?: {
    errorThresholdPercentage?: number;
    resetTimeout?: number;
  };
}

/**
 * Standardized Outbound HTTP Client
 * 
 * Features:
 * 1. Exponential Retries (axios-retry)
 * 2. Circuit Breaker (opossum)
 * 3. Standard Timeouts
 * 4. Header Propagation (X-Request-ID via AsyncLocalStorage)
 */
export function createOutboundClient(options: OutboundClientOptions): AxiosInstance {
  const client = axios.create({
    baseURL: options.baseURL,
    timeout: options.timeout || 10000,
  });

  // 1. Exponential Retry Logic with Jitter (Risk 3 Mitigation)
  axiosRetry(client, {
    retries: options.retries ?? 2, // Default to 2 retries (3 total attempts) to prevent amplification
    retryDelay: (retryCount) => {
      const delay = axiosRetry.exponentialDelay(retryCount);
      const jitter = delay * 0.2 * (Math.random() - 0.5); // +/- 10% jitter
      const finalDelay = Math.max(0, delay + jitter);
      
      const source = process.env.SERVICE_NAME || 'unknown';
      const target = options.serviceName;

      // Phase 21: Track Retry Pressure
      retryAttemptsTotal.inc({ source_service: source, target_service: target });

      logger.warn(
        { service: target, retryCount, delay: finalDelay }, 
        `[Resilience] Retrying request with jitter...`
      );
      return finalDelay;
    },
    retryCondition: (error) => {
      return axiosRetry.isNetworkOrIdempotentRequestError(error) || 
             (error.response?.status ? error.response.status >= 500 : false);
    },
  });

  // 2. Trace Propagation & Retry Tracking Interceptor
  client.interceptors.request.use((config) => {
    const context = contextStorage.getStore();
    if (context?.requestId) {
      config.headers['X-Request-ID'] = context.requestId;
    }
    
    // Add retry tracking header for downstream observability
    const retryCount = (config as any)['axios-retry']?.retryCount || 0;
    if (retryCount > 0) {
      config.headers['X-Retry-Count'] = retryCount.toString();
    }
    
    return config;
  });

  // 3. Circuit Breaker Logic
  const breaker = new CircuitBreaker(async (config: AxiosRequestConfig) => {
    return client.request(config);
  }, {
    timeout: options.timeout || 10000,
    errorThresholdPercentage: options.circuitBreaker?.errorThresholdPercentage || 50,
    resetTimeout: options.circuitBreaker?.resetTimeout || 30000,
  });

  breaker.on('open', () => {
    logger.error(`[Resilience][Circuit] Open for ${options.serviceName}`);
    circuitBreakerState.set({ target_service: options.serviceName }, 1);
  });
  breaker.on('halfOpen', () => {
    logger.warn(`[Resilience][Circuit] Half-Open for ${options.serviceName}`);
    circuitBreakerState.set({ target_service: options.serviceName }, 2);
  });
  breaker.on('close', () => {
    logger.info(`[Resilience][Circuit] Closed for ${options.serviceName}`);
    circuitBreakerState.set({ target_service: options.serviceName }, 0);
  });

  // Initial state registration
  circuitBreakerState.set({ target_service: options.serviceName }, 0);

  // Overriding request method to go through the breaker
  client.request = (async (config: AxiosRequestConfig) => {
    return breaker.fire(config);
  }) as any;

  return client;
}

import { redis } from '@packages/utils';
import type { Request, Response, NextFunction } from 'express';
import { RateLimiterRedis } from 'rate-limiter-flexible';
import type { Redis } from 'ioredis';

/**
 * Standard Rate Limiter
 * Uses Redis to store request counts across distributed instances.
 * Lazy initialization to prevent circular dependency crashes.
 */
let _rateLimiter: RateLimiterRedis | null = null;

const getRateLimiter = () => {
    if (!_rateLimiter) {
        const points = parseInt(process.env.RATELIMIT_POINTS || '1000', 10);
        const duration = parseInt(process.env.RATELIMIT_DURATION || '60', 10);
        
        if (!redis) {
            // Fallback for circular dependency during initialization
            return {
                consume: async () => ({})
            } as any;
        }

        _rateLimiter = new RateLimiterRedis({
            storeClient: redis,
            keyPrefix: 'resilience_ratelimit',
            points: points,
            duration: duration,
        });
    }
    return _rateLimiter;
};

// Export a proxy or just the getter?
// To minimize changes in other files, we export a proxy-like object for the main limiter
export const rateLimiter = {
    consume: (key: string | number) => getRateLimiter().consume(key),
    get: (key: string | number) => (getRateLimiter() as any).get(key),
    delete: (key: string | number) => (getRateLimiter() as any).delete(key),
} as any;

/**
 * RateLimiter wrapper for api-gateway
 */
export class RateLimiter {
  private limiter: RateLimiterRedis;
  
  constructor(client: Redis, keyPrefix: string, points: number, duration: number) {
    this.limiter = new RateLimiterRedis({
      storeClient: client,
      keyPrefix: `resilience_${keyPrefix}`,
      points,
      duration,
    });
  }

  async consume(key: string) {
    return this.limiter.consume(key);
  }
}

/**
 * Multi-Tier Rate Limiter
 * Dynamically adjusts limits based on Tenant Tier (Free/Pro/Enterprise)
 */
export class MultiTierRateLimiter {
  private limiters = new Map<string, RateLimiterRedis>();

  constructor(private client: Redis) {}

  private getLimiter(tier: string, points: number, duration: number) {
    const key = `${tier}:${points}:${duration}`;
    if (!this.limiters.has(key)) {
      this.limiters.set(key, new RateLimiterRedis({
        storeClient: this.client,
        keyPrefix: `resilience_tier_${tier}`,
        points,
        duration,
      }));
    }
    return this.limiters.get(key)!;
  }

  async consume(tenantId: string, tier: string, points: number, duration: number) {
    const limiter = this.getLimiter(tier, points, duration);
    try {
      return await limiter.consume(tenantId);
    } catch (err) {
      throw err;
    }
  }
}

/**
 * Higher-level middleware for Express
 */
export async function rateLimitMiddleware(req: Request, res: Response, next: NextFunction) {
  try {
    const userId = (req as any).user?.id || (req as any).user?.tenantId;
    const key = userId ? `user:${userId}` : `ip:${req.ip || 'unknown'}`;
    
    await rateLimiter.consume(key);
    return next();
  } catch (rejRes) {
    res.status(429).json({
      error: 'Too Many Requests',
      retryAfter: Math.round((rejRes as any).msBeforeNext / 1000) || 60,
    });
  }
}

// tierRateLimiter also needs to be lazy if redis is not ready
let _tierRateLimiter: MultiTierRateLimiter | null = null;
export const getTierRateLimiter = () => {
    if (!_tierRateLimiter) {
        _tierRateLimiter = new MultiTierRateLimiter(redis as any);
    }
    return _tierRateLimiter;
};

// For backward compatibility, but this might still crash if used at top-level elsewhere
// However, most usages are inside functions.
export const tierRateLimiter = {
    consume: (...args: any[]) => (getTierRateLimiter() as any).consume(...args)
} as any;

import { logger } from '@packages/observability';

export async function retry<T>(
  fn: () => Promise<T>,
  retries: number = 3,
  baseDelayMs: number = 1000
): Promise<T> {
  let attempt = 0;
  while (attempt < retries) {
    try {
      return await fn();
    } catch (err: any) {
      attempt++;
      if (attempt >= retries) {
        logger.error(`Exhausted all ${retries} retries.`);
        throw err;
      }
      const delay = baseDelayMs * Math.pow(2, attempt - 1); // exponential backoff
      logger.warn(`Execution failed: ${err.message}. Retrying in ${delay}ms... (Attempt ${attempt}/${retries})`);
      await new Promise(resolve => setTimeout(resolve, delay));
    }
  }
  throw new Error('Unreachable code in retry logic');
}

import { logger } from '@packages/observability';

export type SagaStep<T = any> = {
  name: string;
  action: (data: T) => Promise<any>;
  compensate: (data: T) => Promise<void>;
};

export async function runSaga<T>(sagaName: string, steps: SagaStep<T>[], initialData: T) {
  const completed: SagaStep<T>[] = [];
  logger.info(`Starting Saga: ${sagaName}`);

  try {
    for (const step of steps) {
      logger.debug(`Executing Saga Step: ${step.name}`);
      await step.action(initialData);
      completed.push(step);
    }
    logger.info(`Saga completed successfully: ${sagaName}`);
    return true;
  } catch (err: any) {
    logger.error(`Saga failed at step: ${completed.length < steps.length ? steps[completed.length].name : 'Unknown'}, Error: ${err.message}. Initiating compensation...`);
    
    // Compensation phase (reverse order)
    for (const step of completed.reverse()) {
      try {
        logger.debug(`Compensating Saga Step: ${step.name}`);
        await step.compensate(initialData);
      } catch (compErr: any) {
        logger.error(`CRITICAL: Compensation failed for step ${step.name}. Error: ${compErr.message}`);
      }
    }
    throw new Error(`Saga ${sagaName} aborted and compensated due to: ${err.message}`);
  }
}

import jwt from 'jsonwebtoken';
import type { Request, Response, NextFunction } from 'express';
import { logger } from '@packages/observability';

import { randomBytes } from 'node:crypto';

const RAW_SECRET = process.env.SERVICE_SECRET;
if (!RAW_SECRET && process.env.NODE_ENV === 'production') {
  throw new Error('FATAL: SERVICE_SECRET is not defined in production environment.');
}
// Generate a transient, secure random fallback if not provided in dev
const SERVICE_SECRET = RAW_SECRET || randomBytes(32).toString('hex');

/**
 * Sign a short-lived token for service-to-service communication
 */
export function signServiceToken(serviceName: string): string {
  return jwt.sign(
    { svc: serviceName },
    SERVICE_SECRET,
    { expiresIn: '5m' }
  );
}

/**
 * Middleware to verify service-to-service identity
 */
export function serviceAuth(allowedServices: string[]) {
  return (req: Request, res: Response, next: NextFunction) => {
    const authHeader = req.headers.authorization;
    if (!authHeader?.startsWith('Bearer ')) {
      logger.warn({ path: req.path }, '[ZeroTrust] Missing service token');
      return res.sendStatus(401);
    }

    const token = authHeader.split(' ')[1];
    try {
      const decoded = jwt.verify(token, SERVICE_SECRET);
      
      if (typeof decoded === 'string' || !decoded.svc) {
        logger.error({ token }, '[ZeroTrust] Malformed service token payload');
        return res.sendStatus(403);
      }
      
      if (!allowedServices.includes(decoded.svc)) {
        logger.error(
          { caller: decoded.svc, allowed: allowedServices }, 
          '[ZeroTrust] Unauthorized service caller'
        );
        return res.sendStatus(403);
      }

      // Attach caller info for traceability
      (req as Request & { serviceCaller: string }).serviceCaller = (decoded as any).svc;
      return next();
    } catch (err) {
      logger.error({ err }, '[ZeroTrust] Invalid service token');
      return res.status(403).json({ error: 'Invalid service token' });
    }
  };
}

